contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking a recipient address as input
    function run(address recipient) public payable {
        require(recipient != address(0));

        // record contract balance before the first call
        uint balBefore = address(c).balance;

        // try first call
        bool firstReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // record contract balance after the first call
        uint balAfter = address(c).balance;

        // try second call
        bool secondReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // If the first call did not revert then balance must have decreased by exactly 100
        // and the second call must revert. If the first call reverted, no guarantees.
        assert(firstReverted || ((balBefore == balAfter + 100) && secondReverted));
    }

    receive() external payable {}
}

